#!/usr/bin/env bash

# Config helpers own the portable TOML defaults and the resolved shell snapshot
# used by the CLI and diagnostics modules.

default_config_toml() {
  cat <<'EOF'
# Khuluma configuration (TOML)
# Generated by `khuluma`; safe to edit.

[meta]
config_version = 1

[clean]
repeats_level = 1

[history]
retention_days = 7
audio_retention_days = 2

[swift_parakeet]
model_path = ""
model_version = ""
socket_path = ""

[inline]
autosend = true
process_sound = true
paste_target = "current"
send_mode = "enter"

[debug]
keep_logs = false

[audio.sounds]
cancel = ""
cancel_enabled = true
enabled = true
error = ""
error_enabled = true
process = ""
process_enabled = true
start = ""
start_enabled = true
stop = ""
stop_enabled = true
EOF
}

config_ensure() {
  [[ -f "$KHULUMA_CONFIG_FILE" ]] && return 0
  mkdir -p "$(dirname "$KHULUMA_CONFIG_FILE")"
  default_config_toml >"$KHULUMA_CONFIG_FILE"
}

config_load() {
  need python3
  [[ "${KHULUMA_READ_ONLY_STARTUP:-0}" == "1" ]] || config_ensure
  local cfg_shell=""
  # A loader that fails or prints nothing must not leave the defaults in
  # place silently (autosend defaults to on): fall back to safe settings.
  if cfg_shell="$(
    python3 - "$KHULUMA_CONFIG_FILE" <<'PYEOF'
import fcntl, os, shlex, sys, time, tomllib

path = os.path.expanduser(sys.argv[1])
# Last config that loaded and validated, kept beside it. A half-saved,
# empty or mistyped file falls back to it instead of to the defaults
# (which would, for example, turn autosend back on mid-edit).
last_good = os.path.join(os.path.dirname(path), "." + os.path.basename(path) + ".last-good")
BOOL_KEYS = (
  "audio.sounds.enabled", "audio.sounds.start_enabled", "audio.sounds.stop_enabled",
  "audio.sounds.process_enabled", "audio.sounds.error_enabled", "audio.sounds.cancel_enabled",
  "inline.autosend", "inline.process_sound", "debug.keep_logs", "app.supervise_daemon",
)

class InvalidConfig(ValueError):
  pass

def lookup(data, dotted):
  cur = data
  for part in dotted.split("."):
    if not isinstance(cur, dict) or part not in cur:
      return None
    cur = cur[part]
  return cur

def read_config(p):
  with open(p, "rb") as f:
    raw = f.read()
  text = raw.decode("utf-8")
  if not text.strip():
    raise InvalidConfig("the file is empty")
  data = tomllib.loads(text) or {}
  for key in BOOL_KEYS:
    value = lookup(data, key)
    if value is not None and not isinstance(value, bool):
      raise InvalidConfig(f"{key} must be true or false, not {value!r}")
  return raw, data

def publish(raw):
  if os.environ.get("KHULUMA_READ_ONLY_STARTUP") == "1":
    return
  # Skip quickly when the copy is current; otherwise publish under a lock,
  # and only if config.toml still holds what was read, so a slow reader
  # never replaces a newer copy with older settings.
  try:
    with open(last_good, "rb") as f:
      if f.read() == raw:
        return
  except OSError:
    pass
  try:
    lock_fd = os.open(last_good + ".lock", os.O_WRONLY | os.O_CREAT, 0o600)
  except OSError:
    return
  try:
    deadline = time.monotonic() + 1.0
    while True:
      try:
        fcntl.flock(lock_fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        break
      except BlockingIOError:
        if time.monotonic() >= deadline:
          return
        time.sleep(0.02)
    with open(path, "rb") as f:
      if f.read() != raw:
        return
    tmp = f"{last_good}.{os.getpid()}.{os.urandom(4).hex()}.tmp"
    fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    try:
      with os.fdopen(fd, "wb") as f:
        f.write(raw)
      os.replace(tmp, last_good)
    except OSError:
      try:
        __import__("subprocess").run(["python3", os.environ["KHULUMA_RECOVERY_HELPER"], os.path.abspath(tmp)], check=True)
      except OSError:
        pass
  except OSError:
    pass
  finally:
    os.close(lock_fd)

parse_error = ""
config_source = "file"
try:
  raw, cfg = read_config(path)
  publish(raw)
except (OSError, UnicodeDecodeError, tomllib.TOMLDecodeError, InvalidConfig) as exc:
  parse_error = str(exc).replace("\n", " ") or type(exc).__name__
  try:
    _, cfg = read_config(last_good)
    config_source = "last_good"
  except (OSError, UnicodeDecodeError, tomllib.TOMLDecodeError, InvalidConfig):
    cfg = {}
    config_source = "defaults"

def get(path, default=None):
  cur = cfg
  for part in path.split("."):
    if not isinstance(cur, dict) or part not in cur:
      return default
    cur = cur[part]
  return cur

def b(v, default=False):
  if v is None:
    return default
  return bool(v)

out = {
  "CFG_CONFIG_LOADED": "1",
  "CFG_CONFIG_PARSE_ERROR": parse_error,
  "CFG_CONFIG_SOURCE": config_source,
  "CFG_META_CONFIG_VERSION": str(get("meta.config_version", "")) if isinstance(get("meta.config_version", ""), int) else "",
  "CFG_AUDIO_SOUNDS_START": str(get("audio.sounds.start", "")),
  "CFG_AUDIO_SOUNDS_STOP": str(get("audio.sounds.stop", "")),
  "CFG_AUDIO_SOUNDS_PROCESS": str(get("audio.sounds.process", "")),
  "CFG_AUDIO_SOUNDS_ERROR": str(get("audio.sounds.error", "")),
  "CFG_AUDIO_SOUNDS_CANCEL": str(get("audio.sounds.cancel", "")),
  "CFG_AUDIO_SOUNDS_ENABLED": "1" if b(get("audio.sounds.enabled", True), True) else "0",
  "CFG_AUDIO_SOUNDS_START_ENABLED": "1" if b(get("audio.sounds.start_enabled", True), True) else "0",
  "CFG_AUDIO_SOUNDS_STOP_ENABLED": "1" if b(get("audio.sounds.stop_enabled", True), True) else "0",
  "CFG_AUDIO_SOUNDS_PROCESS_ENABLED": "1" if b(get("audio.sounds.process_enabled", True), True) else "0",
  "CFG_AUDIO_SOUNDS_ERROR_ENABLED": "1" if b(get("audio.sounds.error_enabled", True), True) else "0",
  "CFG_AUDIO_SOUNDS_CANCEL_ENABLED": "1" if b(get("audio.sounds.cancel_enabled", True), True) else "0",
  "CFG_HISTORY_RETENTION_DAYS": str(get("history.retention_days", "7")),
  "CFG_HISTORY_AUDIO_RETENTION_DAYS": str(get("history.audio_retention_days", "2")),
  "CFG_SWIFT_PARAKEET_MODEL_PATH": str(get("swift_parakeet.model_path", "")),
  "CFG_SWIFT_PARAKEET_MODEL_VERSION": str(get("swift_parakeet.model_version", "")),
  "CFG_SWIFT_PARAKEET_SOCKET_PATH": str(get("swift_parakeet.socket_path", "")),
  "CFG_INLINE_AUTOSEND": "1" if b(get("inline.autosend", True), True) else "0",
  "CFG_INLINE_PROCESS_SOUND": "1" if b(get("inline.process_sound", True), True) else "0",
  "CFG_INLINE_PASTE_TARGET": str(get("inline.paste_target", "current")),
  "CFG_INLINE_SEND_MODE": str(get("inline.send_mode", "enter")),
  "CFG_DEBUG_KEEP_LOGS": "1" if b(get("debug.keep_logs", False), False) else "0",
  "CFG_APP_HOTKEY": str(get("app.hotkey", "ctrl+option+space")),
  "CFG_APP_SUPERVISE_DAEMON": "1" if b(get("app.supervise_daemon", True), True) else "0",
  "CFG_CLEAN_REPEATS_LEVEL": str(get("clean.repeats_level", "1")),
}

# No trustworthy settings (invalid file and no valid copy): never send.
if parse_error and config_source == "defaults":
  out["CFG_INLINE_AUTOSEND"] = "0"

for k, v in out.items():
  print(f"{k}={shlex.quote(v)}")
PYEOF
  )" && [[ "$cfg_shell" == *"CFG_CONFIG_LOADED=1"* ]]; then
    eval "$cfg_shell"
  else
    printf 'khuluma: could not load %s; using safe defaults (no autosend)\n' "$KHULUMA_CONFIG_FILE" >&2
    CFG_CONFIG_PARSE_ERROR="the config loader failed"
    CFG_CONFIG_SOURCE="defaults"
    CFG_INLINE_AUTOSEND="0"
  fi
}

config_schema_status() {
  if [[ -n "${CFG_CONFIG_PARSE_ERROR:-}" ]]; then
    echo "invalid"
    return 0
  fi
  local raw="${CFG_META_CONFIG_VERSION:-}"
  if [[ "$raw" =~ ^[0-9]+$ ]] && (( raw == KHULUMA_CONFIG_SCHEMA_VERSION )); then
    echo "ok"
  else
    echo "mismatch"
  fi
}

config_schema_version_label() {
  if [[ -n "${CFG_CONFIG_PARSE_ERROR:-}" ]]; then
    printf "invalid"
    return 0
  fi
  local raw="${CFG_META_CONFIG_VERSION:-}"
  if [[ "$raw" =~ ^[0-9]+$ ]]; then
    printf "v%s" "$raw"
  else
    printf "unset"
  fi
}
